#!/usr/bin/env python3
# admin-device-v1: お店の端末（LINE を使わずに予約管理を開く）
# 何度流しても同じ。元のファイルが想定と違うときは何も変えずに止まる
import hashlib, zlib, base64, json, os, shutil, sys, time
FILES = json.loads('{"supabase/functions/booking/index.ts": {"old": "13a4e0cbcec1bfa98c5a5d9ed2f466a1", "new": "78d7cb9b7c85ddb1411f0388ae206430", "data": ""}, "docs/admin/admin.js": {"old": "fd79b716a2ea1ea363bcf21ba3c05669", "new": "940dbbe9f448458b9b0f309a1f483624", "data": ""}, "docs/admin/admin.css": {"old": "5795113c4c28ec552ec840c3b16e57c6", "new": "cfcfad01d30f83c7bee1c6f6c312df47", "data": ""}, "docs/admin/index.html": {"old": "d2c59abca2c3963e1e0fea1702901788", "new": "17ca02810945f3cc5e96a150b3e395ab", "data": ""}, "tests/e2e_admin_test.py": {"old": "be8e9ddbf1cd19a848021d2c3bb46e22", "new": "2840655b94bd756b3cb133ace9d01f1b", "data": ""}, "README.md": {"old": "8485bbb1aafde3f90e803779ce10eab1", "new": "8bd220f78ba543509fe166ffba8b5867", "data": ""}, "sql/lifeplus_devices_v1.sql": {"old": null, "new": "6fe3d1bcbf70480880a90bca71a68e32", "data": ""}, "tests/device_test.ts": {"old": null, "new": "7df0057a4f77d064a9a13bb39ca6d753", "data": ""}, "tests/e2e_device_test.py": {"old": null, "new": "ee636e44b57516090894402632805dd9", "data": ""}}')
os.chdir(os.path.dirname(os.path.abspath(__file__)))
md5 = lambda b: hashlib.md5(b).hexdigest()
todo = []
for p, f in FILES.items():
    cur = md5(open(p, "rb").read()) if os.path.exists(p) else None
    if cur == f["new"]: print("済み", p); continue
    if cur != f["old"]: print("止めました：", p, "が想定と違います（", cur, "）。何も変えていません"); sys.exit(1)
    todo.append(p)
ts = time.strftime("%Y%m%d%H%M%S")
for p in todo:
    if os.path.exists(p): shutil.copy2(p, p + ".bak_" + ts)
    b = zlib.decompress(base64.b64decode(FILES[p]["data"]))
    assert md5(b) == FILES[p]["new"]
    open(p, "wb").write(b); print("更新" if FILES[p]["old"] else "追加", p)
print("admin-device-v1 OK")
